CREATE TABLE platform_history(id INTEGER PRIMARY KEY,entity TEXT NOT NULL,row_id INTEGER NOT NULL,before_json TEXT,after_json TEXT,undone INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER platform_task_history AFTER UPDATE OF title,due ON tasks WHEN OLD.title<>NEW.title OR OLD.due IS NOT NEW.due BEGIN INSERT INTO platform_history(entity,row_id,before_json,after_json) VALUES('tasks',NEW.id,json_object('title',OLD.title,'due',OLD.due),json_object('title',NEW.title,'due',NEW.due)); END;
CREATE TRIGGER platform_contact_history AFTER UPDATE ON life_contacts BEGIN INSERT INTO platform_history(entity,row_id,before_json,after_json) VALUES('life_contacts',NEW.id,json_object('name',OLD.name,'phone',OLD.phone,'email',OLD.email,'notes',OLD.notes),json_object('name',NEW.name,'phone',NEW.phone,'email',NEW.email,'notes',NEW.notes)); END;
CREATE TRIGGER platform_school_history AFTER UPDATE OF data ON school_records BEGIN INSERT INTO platform_history(entity,row_id,before_json,after_json) VALUES('school_records',NEW.id,json_object('data',OLD.data),json_object('data',NEW.data)); END;
